// d3 · Stamp: one row update per reminder, saying whether it went out.
// Send Emails returns one result per email, in the same order as Due Reminders' items.
const failMsg = j => j.error ? String(j.error.message || j.error.description || j.error) : (Array.isArray(j.rejected) && j.rejected.length ? 'rejected by the mail server: ' + j.rejected.join(', ') : '');
const answers = $('Due Reminders').all();

const rows = [];
$input.all().forEach((sent, i) => {
  const a = answers[i].json;
  if (a.kind !== 'due') return;                               // the "Needs attention" email isn't a booking
  const err = failMsg(sent.json);
  rows.push({ json: { booking_id: a.booking_id, reminder: err ? `Failed ${a.now}: ${err.slice(0, 200)}` : `Sent ${a.now}` } });
});
return rows;

// Check Sends: after every email has been tried, fail loudly if any didn't go out, so e0 emails you.
// Sits on its own branch BELOW the other one: n8n runs the top branch first, so stamps are saved before this runs.
const failMsg = j => j.error ? String(j.error.message || j.error.description || j.error) : (Array.isArray(j.rejected) && j.rejected.length ? 'rejected by the mail server: ' + j.rejected.join(', ') : '');
const ANSWERS = 'Due Reminders';                                 // the node whose items were emailed
const answers = $(ANSWERS).all();
const sends = $('Send Emails').all();

const failed = [];
sends.forEach((s, i) => {
  const err = failMsg(s.json);
  if (!err) return;
  const a = answers[i].json;
  const who = a.kind === 'attention' ? 'the "Needs attention" email' : a.kind === 'doctor' ? `${a.doctor}'s list` : `${a.patient_name} (${a.booking_id})`;
  failed.push(`${who}: ${err}`);
});
if (failed.length) {
  throw new Error(`${failed.length} of ${sends.length} emails failed to send. Failed reminders are retried next morning. ${failed.join(' | ')}`);
}
return [{ json: { sent: sends.length } }];
